import {products,glossary,dataPolicy} from './data.js';
import {buildChecklist} from './rules.js';
const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=s=>String(s??'Not available').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=id=>products.find(p=>p.id===id);let cleanup=[],routeToken=0,compare={gpu:[],cpu:[]};
try{const saved=JSON.parse(localStorage.getItem('atlas-compare')||'{}');for(const t of ['gpu','cpu'])compare[t]=[...new Set((saved[t]||[]).filter(id=>get(id)?.type===t))].slice(0,3)}catch{}
function save(){try{localStorage.setItem('atlas-compare',JSON.stringify(compare))}catch{}$('#count').textContent=compare.cpu.length+compare.gpu.length}
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').classList.remove('show'),3500)}
const icon=type=>type==='gpu'?`<svg viewBox="0 0 200 100" aria-hidden="true"><path d="M12 15h172v69H12zM5 8v82M24 85v8h52v-8" fill="none" stroke="currentColor" stroke-width="3"/><circle cx="60" cy="50" r="27" fill="none" stroke="currentColor" stroke-width="3"/><circle cx="139" cy="50" r="27" fill="none" stroke="currentColor" stroke-width="3"/>${[60,139].map(x=>Array.from({length:8},(_,i)=>`<path d="M${x} 50q5-24 22-13q-11 0-14 16Z" fill="currentColor" transform="rotate(${i*45} ${x} 50)"/>`).join('')).join('')}</svg>`:`<svg viewBox="0 0 200 100" aria-hidden="true"><rect x="62" y="12" width="76" height="76" fill="none" stroke="currentColor" stroke-width="3"/><rect x="76" y="26" width="48" height="48" fill="currentColor"/>${Array.from({length:8},(_,i)=>`<path d="M${68+i*9} 4v8m0 76v8M54 ${19+i*9}h8m76 0h8" stroke="currentColor" stroke-width="3"/>`).join('')}</svg>`;
function addButton(p){return `<button class="compare-add" data-add="${p.id}" aria-pressed="${compare[p.type].includes(p.id)}" aria-label="${compare[p.type].includes(p.id)?'Remove':'Compare'} ${esc(p.name)}">${compare[p.type].includes(p.id)?'Selected ✓':'+ Compare'}</button>`}
function card(p){return `<article class="product"><div class="identity"><span>${esc(p.vendor)}<br><small>${esc(p.generation)}</small></span>${icon(p.type)}</div><h2><a href="#/product/${p.id}">${esc(p.name)}</a></h2><div class="stats"><span><strong>${p.type==='gpu'?p.memory+' GB':p.cores+' cores'}</strong>${esc(p.type==='gpu'?p.memoryType:p.threads+' threads')}</span><span><strong>${p.power} W</strong>${esc(p.powerLabel)}</span></div><p>${p.type==='gpu'?'Ray tracing · AV1 encode':esc(p.socket)+' · '+esc(p.memoryType)}</p><p class="source-note">${p.type==='gpu'?'Reference specification':'Desktop processor'} · Category illustration</p><div class="product-actions"><a href="#/product/${p.id}">View dossier ↗</a>${addButton(p)}</div></article>`}
function tabs(type,dest='compare'){return `<div class="tabs" aria-label="Hardware category"><a class="${type==='gpu'?'active':''}" href="#/${dest}${dest==='compare'?'?type=gpu':''}">${dest==='compare'?'Graphics cards':'GPU explorer'}</a><a class="${type==='cpu'?'active':''}" href="#/${dest==='compare'?'compare?type=cpu':'cpu'}">Processors</a></div>`}
function benchmarks(type){return `<div class="block"><h2>Performance evidence</h2><label>Workload <select id="workload">${(type==='cpu'?['Gaming','Single-thread','Multi-thread','Application rendering']:['Rasterized gaming','Ray-traced gaming','Video editing','GPU rendering']).map(x=>`<option>${x}</option>`).join('')}</select></label><p id="benchmark-message" class="muted" style="margin-top:20px">Verified ${type==='cpu'?'gaming':'rasterized gaming'} measurements are not available in this release. Specifications are not performance scores.</p><a class="textlink" href="#/sources">How we handle benchmark data ↗</a></div>`}
function home(){return `<section class="hero"><div class="hero-copy"><h1 class="intro-in">Find your next<br>powerhouse.</h1><p class="intro-in">Compare CPUs and GPUs, understand their specifications, and discover what your next build needs.</p><div class="actions intro-in"><a class="button" href="#/gpu">Explore hardware <span>↗</span></a><a class="textlink" href="#/compare">Compare parts</a></div></div><div class="media" id="hero-scene">${icon('gpu')}</div><div class="hero-bottom"><span>Desktop CPUs & GPUs<br>Specifications with context. Decisions with confidence.</span><span>Scroll to look beneath the surface ↓<br>Illustrative GPU assembly</span></div></section><section class="film-section" data-scroll-scene><div class="film"><div class="film-visual" id="film-scene">${icon('gpu')}</div><div class="film-copy"><h2>Power. In perspective.</h2><p>A graphics card is a system of parts. Scroll to move around the assembly and see what sits beneath the surface.</p></div><small>Interactive 3D study · Conceptual assembly, not a retail model</small><div class="progress"></div></div></section><section><div class="section-head"><h2>Meet your next part.</h2><p>A focused atlas of desktop hardware. Explore the specifications that matter, then put two or three parts side by side.</p></div><div class="explore-paths"><a class="path" href="#/gpu"><div class="path-art">${icon('gpu')}<span class="arrow">↗</span></div><div><h3>Graphics cards</h3><p>NVIDIA GeForce & AMD Radeon. Memory, features, power and the space your card needs.</p></div><span>${products.filter(p=>p.type==='gpu').length} graphics cards in the atlas</span></a><a class="path" href="#/cpu"><div class="path-art">${icon('cpu')}<span class="arrow">↗</span></div><div><h3>Processors</h3><p>AMD Ryzen & Intel Core. Cores, platforms, memory support and the foundation of your build.</p></div><span>${products.filter(p=>p.type==='cpu').length} processors in the atlas</span></a></div></section><section class="feature-strip"><div><h3>Beyond the bigger number.</h3><p>More cores or memory does not automatically mean faster. Understand the specification before choosing the part.</p><a class="textlink" href="#/sources">Learn the language ↗</a></div><div><h3>Compare like with like.</h3><p>Keep CPUs and GPUs in separate comparisons. Missing performance evidence stays missing, rather than becoming a guess.</p><a class="textlink" href="#/compare">Open comparison ↗</a></div><div><h3>The whole build matters.</h3><p>A socket is only the beginning. Check BIOS support, memory, power delivery and physical clearance.</p><a class="textlink" href="#/build">Plan your upgrade ↗</a></div></section><section class="closing"><h2>Find the right<br>combination.</h2><div><p>One part is a possibility.<br>A considered build brings it together.</p><a class="button" href="#/build">Build around your choice ↗</a></div></section>`}
let filterState={};
function explorer(type){const list=products.filter(p=>p.type===type),sel=(name,label,values)=>`<label>${label}<select name="${name}"><option value="">All ${label.toLowerCase()}</option>${values.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`;return `<div class="page" data-ui><div class="page-title"><div><h1>${type==='gpu'?'Graphics cards':'Processors'}</h1><p class="muted">${type==='gpu'?'Find the graphics card that fits your next build.':'Choose the foundation for your next build.'}</p></div><a class="textlink" href="#/compare?type=${type}">Open ${type.toUpperCase()} comparison ↗</a></div><p class="source-note">Selected established desktop generations. No laptop, workstation or server parts. Verified 30 October 2026.</p><form class="filters" id="filters"><label>Search hardware<input name="search" type="search" placeholder="${type==='gpu'?'Try RTX 4070 or Radeon':'Try Ryzen 7 or Core i5'}" autocomplete="off"></label>${sel('vendor','Manufacturers',[...new Set(list.map(p=>p.vendor))])}<button type="button" class="filter-toggle" aria-expanded="false">More filters</button><div class="filter-extra">${sel('generation','Generations',[...new Set(list.map(p=>p.generation))])}${type==='gpu'?sel('memory','Minimum VRAM',['8','12','16','20','24'])+sel('power','Maximum power',['150','250','350','450'])+sel('feature','Features',['Ray tracing','AV1 encode','DLSS','FSR']):sel('socket','Sockets',['AM5','LGA1700'])+sel('cores','Minimum cores',['4','6','8','12','16'])+sel('igpu','Integrated graphics',['Yes','No'])+sel('memoryType','Memory types',['DDR4','DDR5'])}</div><button type="reset">Reset</button></form><div class="results-bar"><span id="result-count" role="status"></span><label>Sort <select id="sort"><option value="name">Name</option><option value="power">Power: low to high</option><option value="capacity">${type==='gpu'?'VRAM':'Cores'}: high to low</option></select></label></div><div id="results" class="product-list"></div><p class="source-note" style="margin-top:25px">Category drawings identify the kind of component; they are not product photographs. Live prices and comparable performance datasets are not included.</p></div>`}
function updateResults(type){const f=Object.fromEntries(new FormData($('#filters')));filterState[type]=f;let list=products.filter(p=>p.type===type&&(!f.search||`${p.name} ${p.vendor} ${p.generation}`.toLowerCase().includes(f.search.toLowerCase()))&&(!f.vendor||p.vendor===f.vendor)&&(!f.generation||p.generation===f.generation)&&(!f.memory||p.memory>=Number(f.memory))&&(!f.power||p.power<=Number(f.power))&&(!f.feature||p.features.includes(f.feature))&&(!f.socket||p.socket===f.socket)&&(!f.cores||p.cores>=Number(f.cores))&&(!f.igpu||p.igpu===(f.igpu==='Yes'))&&(!f.memoryType||p.memoryType.includes(f.memoryType)));const sort=$('#sort').value;list.sort((a,b)=>sort==='power'?a.power-b.power:sort==='capacity'?(b.memory||b.cores)-(a.memory||a.cores):a.name.localeCompare(b.name));$('#result-count').textContent=`${list.length} ${type==='gpu'?'graphics cards':'processors'}${Object.values(f).some(Boolean)?' · Filters applied':''}`;$('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>No matching hardware.</h2><p>Try a broader search or reset your filters.</p><button id="clear-empty">Reset filters</button></div>';$('#clear-empty')?.addEventListener('click',()=>{$('#filters').reset();setTimeout(()=>updateResults(type),0)})}
function comparison(type,params){if(params.has('ids')){compare[type]=[...new Set(params.get('ids').split(',').filter(id=>get(id)?.type===type))].slice(0,3);save()}const selected=compare[type].map(get);const rows=[...new Set(selected.flatMap(p=>Object.keys(p.specs)))];return `<div class="page" data-ui><div class="page-title"><div><h1>Compare your options.</h1><p class="muted">The details side by side. The tradeoffs in plain language.</p></div><button id="share">Copy comparison link ↗</button></div>${tabs(type)}<div class="selectors">${[0,1,2].map((i)=>{const p=selected[i];return `<div class="selector"><label for="find-${i}">${i===2?'Optional third part':'Choose '+(i===0?'first':'second')+' part'}</label><input id="find-${i}" type="search" placeholder="Search ${type==='gpu'?'graphics cards':'processors'}" data-find="${i}" aria-label="Search slot ${i+1}"><select data-select="${i}" aria-label="Product in slot ${i+1}"><option value="">Select a part</option>${products.filter(p=>p.type===type).map(p2=>`<option value="${p2.id}" ${p?.id===p2.id?'selected':''} ${selected.some((s,j)=>s.id===p2.id&&j!==i)?'disabled':''}>${esc(p2.name)}</option>`).join('')}</select>${p?`<a href="#/product/${p.id}" class="textlink">Product dossier ↗</a><button data-remove="${p.id}" style="float:right" aria-label="Remove ${esc(p.name)}">Remove</button>`:'<p class="muted">Compare specifications within the same hardware category.</p>'}</div>`}).join('')}</div>${selected.length?`<div class="toolbar"><label><input type="checkbox" id="differences"> Show differences only</label><span class="muted">${selected.length}/3 parts selected · ${selected.length<2?'Add another part to compare.':'Different does not automatically mean better.'}</span></div><div class="table-wrap"><table><caption class="muted" style="text-align:left;padding:15px">Manufacturer specifications · scroll horizontally on small screens</caption><thead><tr><th scope="col">Specification</th>${selected.map(p=>`<th scope="col">${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(k=>{const values=selected.map(p=>p.specs[k]||'Not available'),diff=new Set(values).size>1;return `<tr data-different="${diff}"><th scope="row">${esc(k)}</th>${values.map(v=>`<td class="${diff?'different':''}">${esc(v)}</td>`).join('')}</tr>`}).join('')}</tbody></table></div><div class="block"><h2>What actually changes?</h2>${selected.length>1?`<p>${type==='gpu'?`These cards offer ${[...new Set(selected.map(p=>p.memory))].sort((a,b)=>a-b).join(', ')} GB of VRAM. Capacity matters when your workload needs it; it is not a speed ranking.`:`These processors use ${[...new Set(selected.map(p=>p.socket))].join(' and ')}. A platform change can require a new motherboard and memory.`}</p><p>Power ratings range from ${Math.min(...selected.map(p=>p.power))} to ${Math.max(...selected.map(p=>p.power))} W. Manufacturer definitions can differ. Check cooling, connectors and your whole system; do not interpret watts as performance.</p>`:'<p>Select another product to see the meaningful differences.</p>'}<a class="textlink" href="#/build?${type}=${selected[0].id}">Check supporting components ↗</a></div>`:'<div class="empty" style="margin-top:24px"><h2>Two parts. A clearer decision.</h2><p>Select your first two CPUs or GPUs above. Your comparison can be shared with its own link.</p></div>'}${benchmarks(type)}</div>`}
function detail(id){const p=get(id);if(!p)return '<div class="page"><h1>Part not found.</h1><a class="button" href="#/gpu">Explore the catalogue</a></div>';return `<div class="page" data-ui><a class="crumb" href="#/${p.type}">← ${p.type==='gpu'?'Graphics cards':'Processors'}</a><div class="detail-hero"><div class="detail-art">${icon(p.type)}<small>Category illustration · Product photography unavailable</small></div><div><p>${esc(p.vendor)} · ${esc(p.generation)}</p><h1>${esc(p.name)}</h1><p>${esc(p.notes)}</p><div class="actions">${addButton(p)}<a class="button" href="#/build?${p.type}=${p.id}">Build around this part ↗</a></div><p class="source-note" style="margin-top:25px">Verified ${p.verified} · <a href="${esc(p.source)}" target="_blank" rel="noopener">Manufacturer source ↗</a></p></div></div><div class="two-col"><div class="block"><h2>Specification dossier</h2><div class="table-wrap"><table style="min-width:0"><tbody>${Object.entries(p.specs).map(([k,v])=>`<tr><th scope="row">${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div></div><div><div class="block"><h2>Build around this part</h2><ul class="requirements">${p.requirements.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><a class="textlink" href="#/build?${p.type}=${p.id}">Personalize your checklist ↗</a></div>${benchmarks(p.type)}</div></div><div class="block"><h2>Explore alternatives</h2><div class="actions">${products.filter(x=>x.type===p.type&&x.id!==p.id).slice(0,3).map(x=>`<a class="textlink" href="#/compare?type=${p.type}&ids=${p.id},${x.id}">${esc(x.name)} ↗</a>`).join('')}</div></div></div>`}
function build(params){const options=t=>`<option value="">Not selected</option>${products.filter(p=>p.type===t).map(p=>`<option value="${p.id}" ${params.get(t)===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}`;return `<div class="page" data-ui><div class="page-title"><div><h1>Build with the whole picture.</h1><p class="muted">Turn your parts into a practical checklist. No invented compatibility scores.</p></div></div><div class="two-col"><form id="build-form" class="block" style="margin-top:0"><h2>Your upgrade</h2><div class="build-form"><label>Target processor<select name="targetCpu">${options('cpu')}</select></label><label>Target graphics card<select name="targetGpu">${options('gpu')}</select></label><label>Existing CPU<input name="existingCpu" placeholder="e.g. Ryzen 5 3600"></label><label>Existing GPU<input name="existingGpu" placeholder="e.g. GeForce GTX 1660"></label><label>Motherboard model<input name="motherboard" placeholder="Exact model, if known"></label><label>Existing socket<select name="socket"><option value="">Unknown</option><option>AM4</option><option>AM5</option><option>LGA1700</option><option>LGA1200</option><option>LGA1851</option></select></label><label>RAM type<select name="ramType"><option value="">Unknown</option><option>DDR4</option><option>DDR5</option><option>DDR3</option></select></label><label>RAM capacity (GB)<input name="ramCapacity" type="number" min="1" max="2048" placeholder="32"></label><label>PSU model / wattage<input name="psu" placeholder="e.g. exact model, 750 W"></label><label>GPU length clearance (mm)<input type="number" name="clearance" min="1" max="1000" placeholder="340"></label><label>Monitor resolution / refresh<input name="monitor" placeholder="2560 × 1440, 165 Hz"></label><label>Main workload<select name="use"><option>Gaming</option><option>Video editing</option><option>3D rendering</option><option>Software development</option><option>General use</option></select></label><label class="full">Approximate budget (include currency)<input name="budget" placeholder="Optional — pricing is not integrated"></label><button class="button full" type="submit">Create my checklist ↗</button></div><p class="source-note" style="margin-top:20px">Saved in this browser only. Nothing is sent to a server.</p></form><div><div class="block" style="margin-top:0"><h2>Your build checklist</h2><div id="checklist" aria-live="polite"><p>Choose your target parts and enter what you know. Unknown details will remain verification tasks.</p><p class="muted">A matching CPU socket does not confirm motherboard support. PSU wattage does not confirm cable compatibility.</p></div></div><div class="block"><h2>What this can establish</h2><p>Socket and memory-generation mismatches. Part-specific checks for BIOS, cooling, case clearance and power connections.</p><p class="muted">Exact motherboard support, PSU quality and application performance require model-specific documentation or measurements.</p></div></div></div></div>`}
function sources(){return `<div class="page" data-ui><div class="page-title"><div><h1>Evidence before advice.</h1><p class="muted">What the atlas knows, where it comes from, and what remains unknown.</p></div></div><div class="two-col"><div class="block"><h2>Scope & verification</h2><p>${esc(dataPolicy.scope)}</p><p>Specifications were checked against manufacturer pages on 30 October 2026. This is a maintained snapshot, not a live feed. Each product dossier links to its source.</p><p>Board-partner GPU coolers, dimensions, connectors and power limits may differ. Always verify the exact retail model.</p></div><div class="block"><h2>Performance, honestly</h2><p>${esc(dataPolicy.benchmarkStatus)}</p><p>Future results must include application, test date, platform and software versions. Gaming records also need resolution, quality, ray tracing, upscaling and frame-generation state. Average FPS and percentile lows remain distinct.</p><p>Only matched test conditions may be compared. A derived change would use (new measurement − baseline) ÷ baseline × 100. Lower is better for elapsed time; higher is better for throughput.</p></div><div class="block"><h2>Images & pricing</h2><p>${esc(dataPolicy.imageStatus)}</p><p>The interactive GPU is an original, conceptual 3D illustration. It does not depict a particular retail card or an accurate teardown. No video was generated.</p><p>${esc(dataPolicy.priceStatus)}</p><p>3D rendering uses Three.js, MIT licensed. <a class="textlink" href="vendor/THREE-LICENSE.txt">Read the license</a></p></div><div class="block"><h2>Manufacturer references</h2><ul class="source-list">${[...new Map(products.map(p=>[p.source,p])).values()].map(p=>`<li><a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.vendor==='NVIDIA'?'NVIDIA GeForce specification comparison':p.name)} ↗</a></li>`).join('')}</ul></div></div><section style="padding:60px 0 0"><h2>The hardware glossary</h2><div class="glossary">${glossary.map(g=>`<details><summary>${esc(g.term)}</summary><p>${esc(g.definition)}</p></details>`).join('')}</div></section></div>`}
async function render(){const token=++routeToken;cleanup.forEach(f=>f());cleanup=[];const [path,query='']=(location.hash.slice(1)||'/').split('?'),params=new URLSearchParams(query),type=params.get('type')==='cpu'?'cpu':'gpu';$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$$('nav a').forEach(a=>{if(a.hash.split('?')[0]==='#'+path)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const main=$('#main');main.innerHTML=path==='/'?home():path==='/gpu'||path==='/cpu'?explorer(path.slice(1)):path==='/compare'?comparison(type,params):path.startsWith('/product/')?detail(path.split('/')[2]):path==='/build'?build(params):path==='/sources'?sources():'<div class="page"><h1>Page not found.</h1><a href="#/">Return to the atlas</a></div>';document.title=`${$('h1')?.textContent||'Hardware guide'} — SILICON ATLAS`;scrollTo(0,0);main.focus({preventScroll:true});save();
 if(path==='/'){const entrances=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal');entrances.unobserve(e.target)}})},{threshold:.15});document.querySelectorAll('.section-head h2,.section-head p,.path,.feature-strip h3,.feature-strip p,.closing h2,.closing>div').forEach(e=>entrances.observe(e));cleanup.push(()=>entrances.disconnect());try{const {mountHardware}=await import('./scene.js');if(token===routeToken){cleanup.push(mountHardware($('#hero-scene')));cleanup.push(mountHardware($('#film-scene'),{scrollSection:$('.film-section')}))}}catch{if(token===routeToken){$('#hero-scene').innerHTML=icon('gpu');$('#film-scene').innerHTML=icon('gpu')}}}
 if(path==='/gpu'||path==='/cpu'){const t=path.slice(1);for(const [key,value]of Object.entries(filterState[t]||{}))if($('#filters').elements[key])$('#filters').elements[key].value=value;updateResults(t);$('#filters').addEventListener('submit',e=>e.preventDefault());$('#filters').addEventListener('input',()=>updateResults(t));$('#filters').addEventListener('reset',()=>setTimeout(()=>updateResults(t),0));$('#sort').onchange=()=>updateResults(t);$('.filter-toggle').onclick=e=>{const open=$('#filters').classList.toggle('expanded');e.target.setAttribute('aria-expanded',open);e.target.textContent=open?'Fewer filters':'More filters'}}
 if(path==='/compare'){$$('[data-select]').forEach(el=>el.onchange=()=>{let ids=[...compare[type]];ids[Number(el.dataset.select)]=el.value;compare[type]=ids.filter(Boolean);save();location.hash=`/compare?type=${type}&ids=${compare[type].join(',')}`});$$('[data-find]').forEach(el=>el.oninput=()=>{const s=$(`[data-select="${el.dataset.find}"]`);[...s.options].forEach(o=>{o.hidden=!!o.value&&!o.text.toLowerCase().includes(el.value.toLowerCase())})});$('#differences')?.addEventListener('change',e=>$$('tr[data-different=false]').forEach(r=>r.hidden=e.target.checked));$('#share').onclick=async()=>{const url=new URL(location.href);url.hash=`/compare?type=${type}&ids=${compare[type].join(',')}`;try{await navigator.clipboard.writeText(url.href);notify('Comparison link copied.')}catch{prompt('Copy this comparison link',url.href)}}}
 if(path==='/build'){const form=$('#build-form');try{const saved=JSON.parse(localStorage.getItem('atlas-build')||'{}');for(const [key,value]of Object.entries(saved))if(form.elements[key]&&!((key==='targetCpu'&&params.has('cpu'))||(key==='targetGpu'&&params.has('gpu'))))form.elements[key].value=value}catch{}form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));try{localStorage.setItem('atlas-build',JSON.stringify(data))}catch{}const list=buildChecklist(data,products);$('#checklist').innerHTML=`<p>${esc(data.motherboard?'Motherboard: '+data.motherboard:'Exact motherboard not specified')}${data.ramCapacity?' · '+esc(data.ramCapacity)+' GB RAM':''}</p><ul class="checklist">${list.map(i=>`<li><strong>${esc(i.status)} · ${esc(i.title)}</strong>${esc(i.text)}</li>`).join('')}</ul><p class="source-note">This checklist flags known mismatches and open questions. It is not a guarantee that the complete PC will work.</p>`;$('#checklist').scrollIntoView({behavior:'smooth',block:'start'})}}
 $('#workload')?.addEventListener('change',e=>{$('#benchmark-message').textContent=`Verified ${e.target.value.toLowerCase()} measurements are not available in this release. No ranking or performance percentage can be established from specifications alone.`});
}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-add],[data-remove]');if(!btn)return;const p=get(btn.dataset.add||btn.dataset.remove);if(!p)return;const ids=compare[p.type],index=ids.indexOf(p.id);if(index>=0)ids.splice(index,1);else if(ids.length<3)ids.push(p.id);else return notify('Three parts selected. Remove one in Compare to add another.');save();if(location.hash.startsWith('#/compare')){location.hash=`/compare?type=${p.type}&ids=${ids.join(',')}`}else{$$(`[data-add="${p.id}"]`).forEach(b=>{b.setAttribute('aria-pressed',ids.includes(p.id));b.textContent=ids.includes(p.id)?'Selected ✓':'+ Compare';b.setAttribute('aria-label',`${ids.includes(p.id)?'Remove':'Compare'} ${p.name}`)});notify(`${p.name} ${ids.includes(p.id)?'added to':'removed from'} ${p.type.toUpperCase()} comparison.`)}});
$('#menu').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}});window.addEventListener('hashchange',render);render();


